@pytest.mark.parametrize("seed", [seeds.W1, seeds.MAX_E, seeds.MAX_I], ids=["W1", "MAX-E", "MAX-I"]) def test_R60_large_bills_fit_a_360_px_phone(open_app, seed): # qa.md at 360 x 780. The card is not displayed below 1024 px, so the figures are read on the strip and in the sheet. # Even rows carry no .wk (K2-11), so a MAX-E sheet holds none. A failure on a MAX bill is a design finding for the # owner, the CSS stays a byte copy (spec R60). page = open_app(seed=seed, viewport=VIEWPORTS[360]).page problems = [] overflow = page.evaluate("document.documentElement.scrollWidth - innerWidth") strip = page.evaluate(STRIP_TOTAL_JS) if overflow > 0 or strip is None or strip[0] > strip[1]: problems.append(f"before Splits the page overflows by {overflow} px and #stripTotal is {strip}") open_sheet(page) figures = page.evaluate(FIGURES_JS, "#splitsDlg .rbody") if figures["wide"] or not all(figures["found"][selector] for selector in (".r-amount", ".amt", ".r-lines dd")): problems.append(f"in the sheet {figures}") overflow = page.evaluate("document.documentElement.scrollWidth - innerWidth") if overflow > 0: problems.append(f"with the sheet open the page overflows by {overflow} px") > assert not problems, " | ".join(problems) E AssertionError: before Splits the page overflows by 0 px and #stripTotal is [109, 20, False] | in the sheet {'found': {'.r-amount': 1, '.amt': 4, '.r-lines dd': 3, '.wk': 4}, 'wide': ['.r-amount RM 1,193.87 205 > 8', '.amt RM 1,153.65 116 > 8', '.amt RM 15.74 84 > 8', '.amt RM 24.48 84 > 8', '.amt RM 1,193.87 116 > 8', '.r-lines dd RM 1,023.90 97 > 8', '.r-lines dd RM 102.39 79 > 8', '.r-lines dd RM 67.58 70 > 8']} E assert not ['before Splits the page overflows by 0 px and #stripTotal is [109, 20, False]', "in the sheet {'found': {'.r-amount':... 1,193.87 116 > 8', '.r-lines dd RM 1,023.90 97 > 8', '.r-lines dd RM 102.39 79 > 8', '.r-lines dd RM 67.58 70 > 8']}"]
